#include <bits/stdc++.h>
#include <ext/pb_ds/assoc_container.hpp>
#include <ext/pb_ds/tree_policy.hpp>

using namespace std;
using namespace __gnu_pbds;

using Key = tuple<long long, int, int>;
using OrderedTree = tree<Key, null_type, less<Key>, rb_tree_tag,
                         tree_order_statistics_node_update>;

struct Component {
    OrderedTree xTree, yTree;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    long long K;
    cin >> N >> Q >> K;

    vector<long long> A(N + 1);
    for (int i = 1; i <= N; ++i) cin >> A[i];

    vector<int> D(Q + 1);
    vector<char> active(N + 1, true);
    for (int t = 1; t <= Q; ++t) {
        cin >> D[t];
        active[D[t]] = false;
    }

    vector<int> parent(N + 1), sz(N + 1), leftBound(N + 1),
                rightBound(N + 1), head(N + 1), tail(N + 1), next(N + 1, -1);
    vector<Component> comp(N + 1);

    auto findRoot = [&](int v) {
        int r = v;
        while (parent[r] != r) r = parent[r];
        while (parent[v] != v) {
            int p = parent[v];
            parent[v] = r;
            v = p;
        }
        return r;
    };

    auto insertPoint = [&](int root, int p) {
        long long x = p + A[p];
        long long y = p - A[p];
        comp[root].xTree.insert({x, (int)A[p], p});
        comp[root].yTree.insert({y, (int)A[p], p});
    };

    auto countGe = [](const OrderedTree& tr, long long key, int h) -> long long {
        long long end = tr.order_of_key({key + 1, INT_MIN, INT_MIN});
        long long begin = tr.order_of_key({key, h, INT_MIN});
        return end - begin;
    };

    auto countLt = [](const OrderedTree& tr, long long key, int h) -> long long {
        long long end = tr.order_of_key({key, h, INT_MIN});
        long long begin = tr.order_of_key({key, INT_MIN, INT_MIN});
        return end - begin;
    };

    auto countLe = [](const OrderedTree& tr, long long key, int h) -> long long {
        long long end = tr.order_of_key({key, h, INT_MAX});
        long long begin = tr.order_of_key({key, INT_MIN, INT_MIN});
        return end - begin;
    };

    auto countGt = [](const OrderedTree& tr, long long key, int h) -> long long {
        long long end = tr.order_of_key({key + 1, INT_MIN, INT_MIN});
        long long begin = tr.order_of_key({key, h, INT_MAX});
        return end - begin;
    };

    auto mergeComponents = [&](int u, int v) -> long long {
        int ru = findRoot(u), rv = findRoot(v);
        if (ru == rv) return 0;

        int big = ru, small = rv;
        if (sz[big] < sz[small]) swap(big, small);

        bool smallIsLeft = leftBound[small] < leftBound[big];
        long long added = 0;

        for (int p = head[small]; p != -1; p = next[p]) {
            long long x = p + A[p];
            long long y = p - A[p];
            int h = (int)A[p];

            if (smallIsLeft) {
                added += countGe(comp[big].xTree, x + K, h);
                added += countLt(comp[big].yTree, y + K, h);
            } else {
                added += countLe(comp[big].xTree, x - K, h);
                added += countGt(comp[big].yTree, y - K, h);
            }
        }

        for (int p = head[small]; p != -1; p = next[p])
            insertPoint(big, p);

        next[tail[big]] = head[small];
        tail[big] = tail[small];
        sz[big] += sz[small];
        leftBound[big] = min(leftBound[big], leftBound[small]);
        rightBound[big] = max(rightBound[big], rightBound[small]);
        parent[small] = big;

        comp[small].xTree.clear();
        comp[small].yTree.clear();

        return added;
    };

    for (int i = 1; i <= N; ++i) {
        if (!active[i]) continue;
        parent[i] = i;
        sz[i] = 1;
        leftBound[i] = rightBound[i] = head[i] = tail[i] = i;
        insertPoint(i, i);
    }

    long long current = 0;
    for (int i = 1; i < N; ++i) {
        if (active[i] && active[i + 1])
            current += mergeComponents(i, i + 1);
    }

    vector<long long> answer(Q + 1);
    answer[Q] = current;

    for (int t = Q; t >= 1; --t) {
        int p = D[t];
        active[p] = true;
        parent[p] = p;
        sz[p] = 1;
        leftBound[p] = rightBound[p] = head[p] = tail[p] = p;
        next[p] = -1;
        insertPoint(p, p);

        if (p > 1 && active[p - 1])
            current += mergeComponents(p, p - 1);
        if (p < N && active[p + 1])
            current += mergeComponents(p, p + 1);

        answer[t - 1] = current;
    }

    for (long long value : answer) cout << value << '\n';
    return 0;
}
